<?php
declare(strict_types=1);
namespace App\BusinessModules\Core\Reporting\Infrastructure\Jobs;
use App\BusinessModules\Core\Reporting\Application\Subscriptions\ReportSubscriptionScheduleCalculator; use App\BusinessModules\Core\Reporting\Domain\Contracts\{ReportSubscriptionDeliveryDispatcher,ReportSubscriptionDeliveryStore,ReportSubscriptionStore}; use DateTimeImmutable; use Illuminate\Bus\Queueable; use Illuminate\Contracts\Queue\ShouldQueue; use Illuminate\Foundation\Bus\Dispatchable; use Illuminate\Support\Facades\DB;
final class ScheduleDueReportSubscriptionsJob implements ShouldQueue { use Dispatchable,Queueable; public function handle(ReportSubscriptionStore $subscriptions,ReportSubscriptionDeliveryStore $deliveries,ReportSubscriptionDeliveryDispatcher $dispatcher,ReportSubscriptionScheduleCalculator $schedule):void{$ids=DB::transaction(function()use($subscriptions,$deliveries,$schedule){$now=new DateTimeImmutable();$ids=[];foreach($subscriptions->selectDueLocked($now,(int)config('reporting_subscriptions.scheduler_batch_size')) as $s){if($s->nextRunAt===null || !hash_equals(hash('sha256',$s->executionInputBytes),$s->executionInputHash->value)){$subscriptions->disableLocked($s,'definition_changed');continue;}$d=$deliveries->createCalendarScheduledLocked($s,$s->nextRunAt,$s->executionInputBytes,$s->executionInputHash,$s->transitionVersion);$subscriptions->advanceNextRunLocked($s,$schedule->next($s,$s->nextRunAt));$ids[]=$d->id;}return $ids;});foreach($ids as $id)$dispatcher->dispatch($id,0);} }
